export const $ = s => document.querySelector(s);
export const esc = v => String(v).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const intro = (tag,title,desc) => `<section class="intro"><div><div class="eyebrow">${tag}</div><h1>${title}</h1></div><p>${desc}</p></section>`;
export function read(key,initial){try{return JSON.parse(localStorage.getItem('cw-'+key))??initial}catch{return initial}}
export function save(key,value){try{localStorage.setItem('cw-'+key,JSON.stringify(value))}catch{}}
export function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
